import time

def biseccion(f, a, b, tol=1e-10, max_iter=200):
    if f(a) * f(b) >= 0:
        raise ValueError("Bolzano no se cumple")
    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol or (b - a) / 2 < tol:
            return c, k
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    raise RuntimeError("No convergió")

def newton(f, df, x0, tol=1e-10, max_iter=100):
    x = x0
    for k in range(max_iter):
        if abs(df(x)) < 1e-14:
            raise RuntimeError("Derivada cero")
        x_nuevo = x - f(x) / df(x)
        if abs(x_nuevo - x) < tol:
            return x_nuevo, k
        x = x_nuevo
    raise RuntimeError("No convergió")

def secante(f, x0, x1, tol=1e-10, max_iter=100):
    x_prev, x = x0, x1
    for k in range(max_iter):
        fx = f(x)
        fx_prev = f(x_prev)
        if abs(fx - fx_prev) < 1e-14:
            raise RuntimeError("Denominador cero")
        x_nuevo = x - fx * (x - x_prev) / (fx - fx_prev)
        if abs(x_nuevo - x) < tol:
            return x_nuevo, k
        x_prev, x = x, x_nuevo
    raise RuntimeError("No convergió")

f = lambda x: x**3 - x - 2
df = lambda x: 3*x**2 - 1

print(f"{'Método':<15} {'Raíz':>20} {'Iteraciones':>12} {'Tiempo (ms)':>12}")
print("-" * 62)

metodos = [
    ("Bisección", lambda: biseccion(f, 1, 2)),
    ("Newton",    lambda: newton(f, df, 1.5)),
    ("Secante",   lambda: secante(f, 1, 2)),
]

for nombre, metodo in metodos:
